}

function DialogDescription({
  className,
  ...props
}: DialogPrimitive.Description.Props) {
  return <DialogPrimitive.Description className={cn("text-sm text-ink-3", className)} {...props} />
}

export {
  Dialog,
  DialogClose,
  DialogContent,
